    var M = {"john":{"pt":"«Iavé é misericordioso»"},"mary":{"pt":"Incerto — «amada», «amargura» ou «filha desejada»"},"muhammad":{"pt":"«O louvado», «digno de louvor»"},"alexander":{"pt":"«Defensor dos homens» (aléxō «defender» + anḗr «homem»)"},"joseph":{"pt":"«Ele acrescentará» / «que Deus acrescente»"},"michael":{"pt":"«Quem é como Deus?»"},"george":{"pt":"«Agricultor, lavrador da terra» (gē «terra» + ergon «trabalho»)"},"sophia":{"pt":"«Sabedoria»"},"fatima":{"pt":"«Aquela que desmama / se abstém» (raiz f-ṭ-m)"},"ali":{"pt":"«Alto, elevado, sublime» (raiz ʿ-l-w)"},"krishna":{"pt":"«Escuro, negro» (pela tez azul-enegrecida da divindade)"},"rama":{"pt":"«Agradável, encantador, deleitável» (raiz ram- «agradar, deleitar»)"},"david":{"pt":"«Amado»"},"daniel":{"pt":"«Deus é o meu juiz» (dān «julgar» + ʼēl «Deus»)"},"peter":{"pt":"«Rocha, pedra» — cunhado por Jesus para traduzir o aramaico Kēfā"},"paul":{"pt":"«Pequeno, humilde»"},"thomas":{"pt":"«Gêmeo»"},"abraham":{"pt":"«Pai de muitas nações»"},"isaac":{"pt":"«Ele ri» / «ele rirá»"},"jacob":{"pt":"«Suplantador», «aquele que segura o calcanhar»"},"moses":{"pt":"«Retirado das águas» (tradicional)"},"solomon":{"pt":"«Paz» (de shalom)"},"matthew":{"pt":"«Dom de Javé»"},"adam":{"pt":"«Homem; humanidade», de adamah «terra, solo»"},"noah":{"pt":"«Descanso, conforto»"},"gabriel":{"pt":"«Deus é a minha força»"},"elijah":{"pt":"«O meu Deus é Javé»"},"sarah":{"pt":"«Princesa, mulher nobre»"},"anna":{"pt":"«Graça, favor»"},"elizabeth":{"pt":"«O meu Deus é um juramento»"},"omar":{"pt":"«Longevo, florescente, próspero»"},"aisha":{"pt":"«Viva, cheia de vida, próspera»"},"khadija":{"pt":"«Nascida cedo, criança prematura»"},"abdullah":{"pt":"«Servo de Deus»"},"hassan":{"pt":"\"Bom, belo, formoso\""},"husayn":{"pt":"\"Pequeno Hasan\", \"o pequeno belo\""},"zaynab":{"pt":"Uma planta do deserto perfumada e florida"},"nicholas":{"pt":"\"Vitória do povo\""},"helen":{"pt":"Incerto — provavelmente \"tocha, a resplandecente\""},"catherine":{"pt":"Incerto — ligado por etimologia popular a \"puro\""},"margaret":{"pt":"\"Pérola\""},"philip":{"pt":"\"Amante dos cavalos\""},"theodore":{"pt":"\"Dádiva de Deus\""},"anthony":{"pt":"Um nome de gens romano de origem incerta, talvez etrusca"},"julia":{"pt":"\"Jovem\"; forma feminina do nome de gens Iulius, ligada a Júpiter"},"lakshmi":{"pt":"\"Sinal, marca\" → \"boa sorte, prosperidade\""},"arjun":{"pt":"\"Brilhante, branco, prateado, claro\""},"sita":{"pt":"\"Sulco\" (a linha traçada pelo arado)"},"ganesh":{"pt":"\"Senhor dos ganas (hostes, tropas)\""},"priya":{"pt":"\"Amada, querida\""}};
    var B = {"john":{"pt":"Um dos nomes mais difundidos da Terra. O hebraico Yōḥānān, usado por John, o Batista, e John, o Apóstolo, passou ao grego como Iōánnēs e ao latim como Iohannes, espalhando-se depois por toda a cristandade. A Europa Ocidental manteve o J/G inicial (John, Jean, Juan, Giovanni); o mundo eslavo oriental transformou-o em Ivan; e o Qurʼan preserva uma forma árabe paralela, Yaḥyā, para o mesmo profeta."},"mary":{"pt":"O nome da mãe de Jesus e de Miriam, irmã de Moisés, e por meio delas um dos nomes femininos mais venerados do mundo. O grego Maria e o latim Maria difundiram-no por todas as línguas cristãs; o Qurʼan traz Maryam, a única mulher nele nomeada, de modo que o nome é igualmente central no mundo islâmico."},"muhammad":{"pt":"O nome do Profeta do islão e, segundo muitas contagens, o nome masculino mais comum da Terra. Do árabe muḥammad (raiz ḥ-m-d, «louvar»), viajou com o islão para todas as línguas do mundo muçulmano, cada uma remodelando os seus sons: Mehmet em turco, Mohammad em persa/urdu, Muhamed em bósnio, Mamadou na África Ocidental, Muhammad/Mohd no Sudeste Asiático."},"alexander":{"pt":"Levado por três continentes por Alexander, o Grande, cujas conquistas fincaram o nome da Grécia até a Índia. Mais tarde o cristianismo difundiu-o ainda mais através de santos e papas. Quase em toda parte encurta-se afetuosamente — Alex, Sasha, Sander, Xander, Ale, Iskandar — e até entrou no mundo islâmico como Iskandar/Sikandar."},"joseph":{"pt":"O nome do patriarca Joseph, vendido para o Egito, e de são Joseph, esposo de Mary. O hebraico Yōsēf passou pelo grego Iōsḗph e pelo latim Ioseph para todas as línguas cristãs, contraindo-se em José na Ibéria, Giuseppe na Itália e Josef nos mundos germânico e eslavo. O Qurʼan narra a história do mesmo patriarca sob a forma árabe paralela Yūsuf, que se espalhou com o islão da África Ocidental à Indonésia."},"michael":{"pt":"Originalmente o nome do arcanjo Michael, o líder guerreiro das hostes celestiais, cujo culto levou o nome por toda a cristandade. O grego Michaḗl e o latim Michael ramificaram-se em Michel, Miguel, Michele, Michael e o eslavo Mikhail, suavizando pelo caminho a gutural hebraica ḵ para um som k ou h. O Qurʼan chama o mesmo anjo de Mīkāʼīl, dando uma forma islâmica paralela usada do Irã à África Ocidental."},"george":{"pt":"Do grego Geōrgios, formado sobre geōrgós “lavrador, trabalhador da terra”, o nome deve seu vasto alcance a são George, o mártir matador de dragões venerado por toda a cristandade e padroeiro da Inglaterra, da Geórgia e da Etiópia. Ele se ramifica em Jorge, Giorgio, Georg e Jerzy, e o mundo eslavo oriental o dividiu em dois nomes vivos — o erudito Georgy e o cotidiano Yuri. No Cáucaso é um favorito nacional: o georgiano Giorgi e o armênio Gevorg."},"sophia":{"pt":"O grego sophía significa simplesmente “sabedoria”, personificada como virtude e consagrada na grande igreja de Hagia Sophia, em Constantinopla, “Santa Sabedoria”. Levado pela tradição bizantina e ortodoxa e usado por imperatrizes e santas, espalhou-se como Sofia, Sophie, Zsófia e Zofia. Hoje é um dos nomes de menina mais populares do mundo, no topo dos registros de nascimento por toda a Europa e as Américas; o russo lhe dá o terno diminutivo Sonya."},"fatima":{"pt":"O nome de Fāṭima al-Zahrāʼ, filha do Profeta Muhammad e esposa de ʿAlī, e por isso um dos nomes femininos mais honrados do islã — sobretudo na tradição xiita, na qual ela é a mãe dos imames. Da raiz árabe f-ṭ-m (“desmamar”), espalhou-se com o islã e foi se suavizando pelo caminho: o turco o encurta para Fatma, o persa arredonda a terminação em Fāṭeme, e o Sul e o Sudeste Asiático conservam a forma mais plena Fatimah. Nos Bálcãs perdura como Fatima com o diminutivo carinhoso Fata."},"ali":{"pt":"O nome de ʿAlī ibn Abī Ṭālib, primo e genro do Profeta Muhammad, quarto califa na tradição sunita e primeiro imã do islã xiita — o que faz de Ali um dos nomes centrais do mundo muçulmano e também um dos “belos nomes”, pois al-ʿAlī é um atributo de Deus. Do árabe ʿAlī (raiz ʿ-l-w, “ser alto”), os sons atravessam as línguas quase inalterados: Ali em turco e persa, Ali em urdu, Alija em bósnio, Aliyu na África Ocidental. No Ocidente é mais conhecido pelo pugilista Muhammad Ali."},"krishna":{"pt":"Krishna é o oitavo avatar de Vishnu e uma das divindades mais amadas do hinduísmo — o vaqueiro tocador de flauta de Vrindavan e o sábio condutor de carro do Bhagavad Gita. O sânscrito kṛṣṇa significa literalmente \"escuro, negro\", descrevendo sua tez, e deu origem a formas afetuosas como Kanha e o tâmil Kannan. Como nome próprio, é comum em toda a Índia e em toda a diáspora hindu; sua difusão pelo Sudeste Asiático deu-se por meio do teatro de sombras wayang e do Mahabharata."},"rama":{"pt":"Rama é um avatar de Vishnu e o herói do Ramayana, o rei ideal de Ayodhya, cuja história está entre as mais recontadas do mundo. O sânscrito rāma significa \"aprazível, encantador\". Acima de tudo, foi a epopeia que levou o nome por todo o Sudeste Asiático: os reis tailandeses da dinastia Chakri adotam todos o nome de reinado Rama, a própria Ayutthaya recebeu o nome de Ayodhya, terra natal de Rama, e Rama continua vivo no Reamker cambojano (como Preah Ream), no wayang javanês e balinês, e no Phra Lak Phra Ram laociano."},"david":{"pt":"O nome do rei-pastor de Israel, segundo rei e matador de Golias, venerado igualmente no judaísmo, no cristianismo e no islão. O hebraico Dāwīḏ passou pelo grego e pelo latim para todas as línguas europeias quase sem alteração, enquanto o georgiano Davit e o etíope Dawit se tornaram nomes reais por direito próprio. Como David também é um profeta do Qurʼan, uma linha islâmica paralela percorre o árabe Dāwūd — Daud, Davut, Daudi — por todo o mundo muçulmano."},"daniel":{"pt":"Do profeta visionário do Livro de Daniel, cuja fé na cova dos leões fez do nome um símbolo de firmeza. O hebraico Dāniyyēl passou pelo grego Daniḗl e pelo latim Daniel para o Ocidente cristão, mantendo uma grafia notavelmente estável, enquanto o mundo eslavo o remodelou em Daniil e Danylo. Daniel é também honrado na tradição islâmica como o profeta Dāniyāl, cujo túmulo em Susa continua sendo lugar de peregrinação."},"peter":{"pt":"O nome que Jesus deu ao pescador Simão — o grego Pétros, \"rocha\", tradução do apelido aramaico Kēfā — fazendo dele a rocha sobre a qual a Igreja foi edificada. Como primeiro papa, são Pedro levou o nome a toda terra cristã: latim Petrus, francês Pierre, espanhol Pedro, italiano Pietro, russo Pyotr. Os cristãos orientais mantiveram o grego Petros, e os cristãos de língua árabe dizem Buṭrus."},"paul":{"pt":"O cognome romano Paulus, «pequeno», adotado pelo apóstolo Paul — nascido Saul de Tarso — cujas cartas moldaram a teologia cristã e levaram o seu nome por todo o mundo. As igrejas de língua grega conheciam-no como Paûlos, e do latim Paulus surgiram Pablo, Paolo, Paulo, Paweł e o eslavo Pavel. O arménio remodelou-o de forma notável para Poġos, e os cristãos de língua árabe chamam-lhe Būlus."},"thomas":{"pt":"A alcunha do apóstolo que duvidou da Ressurreição até tocar nas chagas de Cristo — aramaico Tʼōmā, «gémeo», que os Evangelhos gregos também traduzem como Dídymos. Através do grego Thōmâs e do latim Thomas, difundiu-se pelo Ocidente como Thomas, Tomás, Tommaso e Tomasz, enquanto o oriente eslavo o remodelou em Foma e Khoma. Os cristãos de língua árabe preservam o som aramaico como Tūmā."},"abraham":{"pt":"O patriarca venerado como pai dos crentes nas três religiões abraâmicas. O hebraico Avraham, «pai de muitas nações», passou pelo grego Abraám e pelo latim Abraham para o Ocidente cristão, enquanto o Qurʼan apresenta a forma paralela Ibrāhīm — um dos nomes masculinos mais comuns em todo o mundo muçulmano, de Marrocos à Indonésia. O neerlandês abrevia-o para Bram; o Cáucaso remodela-o como Ibragim."},"isaac":{"pt":"O filho de Abraham e segundo patriarca, cujo nome hebraico Yitzḥaq significa «ele ri». O grego Isaák e o latim Isaac levaram-no para ocidente — italiano Isacco, alemão e russo Isaak —, enquanto o Qurʼan chama o mesmo profeta Isḥāq. Favorito tanto entre famílias judaicas como cristãs e muçulmanas, foi usado por figuras que vão de Isaac Newton ao escritor russo Isaak Babel."},"jacob":{"pt":"O terceiro patriarca, mais tarde rebatizado Israel; o seu nome hebraico Yaʿaqov deu origem a uma das árvores genealógicas mais emaranhadas de toda a onomástica. O latim Iacobus produziu Jacob, Jakob e o eslavo Yakov, mas uma variante do latim vulgar, Iacomus, separou-se para dar o italiano Giacomo, o francês Jacques, o inglês James e os ibéricos Diego, Santiago, Tiago e Jaime — todos duplicados de um único e mesmo nome. O Qurʼan conserva o profeta como Yaʻqūb."},"moses":{"pt":"O profeta que conduziu os israelitas para fora do Egito; o seu nome hebraico Mosheh é tradicionalmente interpretado como \"tirado das águas\". Através do grego Mōÿsês e do latim Moyses, difundiu-se como Moses, o francês Moïse, o espanhol Moisés e o italiano Mosè, ao passo que Mūsā — mencionado no Qurʼan mais vezes do que qualquer outro profeta — tornou-se um dos grandes nomes do mundo muçulmano, usado pelo imperador do Mali Mansa Musa."},"solomon":{"pt":"O rei sábio, filho de David; o seu nome hebraico Shlomoh deriva de shalom, \"paz\". O grego Solomṓn e o latim Salomon deram Solomon, o francês Salomon, o italiano Salomone e o português Salomão. Os imperadores da Etiópia reivindicaram descendência dele na dinastia salomónica, e o Qurʼan honra-o como o rei-profeta Sulaymān — origem do turco Süleyman, usado pelo maior dos sultões otomanos."},"matthew":{"pt":"O nome do apóstolo e evangelista Matthew, o cobrador de impostos chamado por Jesus e tradicional autor do primeiro Evangelho. O hebraico Mattityāhū (\"dádiva de Javé\") foi abreviado no grego para Maththaîos e latinizado como Matthaeus, espalhando-se depois por toda a cristandade como Matteo, Mateo, Matthieu, Mateusz e o eslavo Matvei. Os cristãos de língua árabe conhecem o evangelista como Mattā."},"adam":{"pt":"O nome do primeiro homem, formado da terra no Génesis e nomeado vinte e cinco vezes no Qurʼan, e por isso partilhado igualmente por judeus, cristãos e muçulmanos. De modo invulgar, quase não precisa de transformação ao passar de uma língua para outra — Adam em inglês, alemão, polaco e árabe, Adán em espanhol, Adamo em italiano, Adem em turco e bósnio, Adamu em hauçá e suaíli. No mundo islâmico, Ādam é muito comum como nome próprio do quotidiano."},"noah":{"pt":"O construtor da arca que sobreviveu ao Dilúvio, honrado tanto na Bíblia como no Qurʼan. O hebraico Nōaḥ passou pelo grego Nôe e pelo latim Noe até dar o romance Noé e o italiano Noè, ao passo que o inglês conservou a forma mais completa Noah. No século vinte e um, Noah disparou para o topo das listas de nomes masculinos nos Estados Unidos e em toda a Europa, e foi até retomado por empréstimo no Japão como o nome moderno Noa. O Qurʼan narra a mesma história sob a forma árabe paralela Nūḥ, um dos cinco maiores profetas do islão."},"gabriel":{"pt":"O nome do arcanjo que revela visões a Daniel, anuncia o nascimento de John e de Jesus e que no islã dita o Qurʼan a Muhammad. O hebraico Gaḇrīʼēl tornou-se o grego Gabriḗl e o latino Gabriel, permanecendo próximo da sua origem em francês, espanhol, português e alemão, suavizando-se no italiano Gabriele e no eslavo Gavriil / Gavrilo. O Qurʼan chama o mesmo anjo de Jibrīl, e na Etiópia o arcanjo Gabrʼel é profundamente venerado."},"elijah":{"pt":"O nome do ardente profeta do século IX a.C. que enfrentou os sacerdotes de Baal no monte Carmel e foi arrebatado ao céu num turbilhão. No grego do Novo Testamento ele é Ēlías, que deu o latino Elias e as muitas formas europeias Elias / Élie / Ilie, enquanto o mundo eslavo oriental fez dele o cotidiano Ilya. A forma mais completa, Elijah, tornou-se um dos nomes ingleses modernos mais populares. O Qurʼan honra o mesmo profeta sob a forma árabe paralela Ilyās."},"sarah":{"pt":"O nome da esposa do patriarca Abraham, que no Gênesis é renomeada de Sarai para Sarah, «princesa». O grego Sárra e o latim Sara levaram-no por todo o mundo cristão, onde se tornou um dos nomes femininos mais populares da era moderna. Como Abraham é um patriarca comum, o mesmo nome perdura no mundo muçulmano como Sāra, e varia afetuosamente de Zara ao finlandês Saara."},"anna":{"pt":"Do hebraico Ḥannāh, a mãe do profeta Samuel, um nome que significa «graça». O grego transcreveu-o como Ánna — levado no Evangelho de Lucas pela profetisa Anna — e através do latim tornou-se um dos nomes femininos mais difundidos da Europa, honrado ainda como o nome de santa Anne, mãe da Virgem Mary. O inglês conserva tanto Anna, de origem grega, como Hannah, restaurado do hebraico, como um dupleto, e a mesma figura surge no islã como Ḥanna, a mãe de Mary."},"elizabeth":{"pt":"Do hebraico Elišévaʿ, a esposa de Aaron e, no Evangelho de Lucas, a mãe de John o Batista. O grego Elisábet e o latim Elisabeth difundiram-no por toda a cristandade, onde foi levado por santos e por uma longa linhagem de rainhas, sobretudo Elizabeth I e Elizabeth II de Inglaterra. Na península Ibérica o mesmo nome foi remodelado num famoso ramo derivado, Isabel (italiano Isabella), enquanto os mundos eslavo e húngaro lhe deram Yelizaveta e Erzsébet."},"omar":{"pt":"Levado por ʿUmar ibn al-Khattāb, companheiro do Profeta e segundo califa rāshidūn cujo reinado moldou o primeiro Estado islâmico, ʿUmar é um dos nomes masculinos clássicos do mundo muçulmano. Da raiz árabe ʿ-m-r (“viver, prosperar”), significa “longevo, próspero”. Transformou-se no turco Ömer e no bósnio Omer, e chegou ao Ocidente por meio de figuras como Omar Sharif. Um nome hebraico sem relação, Omar — um neto de Esaú no Gênesis — é apenas uma coincidência sonora à parte."},"aisha":{"pt":"O nome de ʿĀʼisha bint Abī Bakr, esposa do Profeta Muhammad célebre como erudita e transmissora de hadices, o que o tornou um dos nomes femininos mais populares de todo o mundo muçulmano. Da raiz árabe ʿ-y-sh (“viver”), significa “viva, com vida”. O turco o transformou em Ayşe — por muito tempo o nome feminino mais comum da Turquia —, enquanto no Magrebe se usa Aïcha e no Sul da Ásia Ayesha. Nas últimas décadas, também figurou amplamente no Reino Unido, na França e nos Estados Unidos."},"khadija":{"pt":"Khadīja bint Khuwaylid foi a primeira esposa do Profeta Muhammad, uma rica mercadora de Meca e a primeira pessoa a aceitar o islã; desde então o seu nome tem sido muito estimado. Deriva da raiz árabe kh-d-j, associada a uma criança “nascida cedo” ou prematura. O turco o traz como Hatice, a África Ocidental como o hauçá Hadiza e o senegalês Khady, e o suaíli como Hadija. Junto com Fatima e Aisha, figura entre os nomes femininos mais comuns do mundo muçulmano."},"abdullah":{"pt":"Um nome teofórico que significa “servo de Deus”, formado por ʿabd (“servo”) e Allāh. Foi o nome do pai do Profeta Muhammad, ʿAbd Allāh ibn ʿAbd al-Muttalib, e um hadice indica ʿAbdullāh e ʿAbd al-Rahmān como os nomes mais amados por Deus — por isso está entre os nomes mais recomendados no islã. Percorre o mundo muçulmano com leves mudanças fonéticas: o persa Abdollah, os magrebinos Abdallah e Abdellah, o nigeriano Abdullahi, o oeste-africano francófono Abdoulaye e o bósnio Abdulah."},"hassan":{"pt":"Ḥasan (raiz ḥ-s-n, “ser bom, belo”) era o nome de Hasan ibn Ali, neto mais velho do Profeta Muhammad e segundo imame xiita. É quase sempre emparelhado com o nome do irmão mais novo — Hasan e Husayn juntos. Levado pelo islã por todo o mundo, manteve uma forma notavelmente estável (Hasan em turco, Hasan/Haso em bósnio) e continua a ser um dos nomes masculinos mais comuns do mundo muçulmano."},"husayn":{"pt":"Ḥusayn é o diminutivo de Ḥasan — «pequeno Hasan», «o pequeno formoso». Foi usado por Husayn ibn Ali, neto mais novo do Profeta, cujo martírio na batalha de Carbala em 680 d.C. tornou o nome o coração emocional do islão xiita, comemorado todos os anos no Ashura. As suas formas percorrem o mundo muçulmano: o persa Hossein, o turco Hüseyin, o Hussain do Sul da Ásia e o Hussein árabe usado por Saddam Hussein e pelo rei Hussein da Jordânia."},"zaynab":{"pt":"Zaynab é o nome de uma planta do deserto perfumada e florida. Foi usado por uma filha do Profeta Muhammad, Zaynab bint Muhammad, e pela sua neta Zaynab bint Ali, irmã de Husayn e venerada heroína da tragédia de Carbala. O nome floresce por todo o mundo muçulmano, sobretudo como o turco Zeynep — durante anos o nome feminino mais popular da Turquia — e como o oeste-africano Zenabou."},"nicholas":{"pt":"Do grego Nikólaos, «vitória do povo», difundido por toda a cristandade pelo culto de são Nicholas de Mira — o bispo do século IV cuja lenda das prendas se tornou Santa Claus, nome ele próprio desgastado a partir do neerlandês Sinterklaas. Quase por toda a parte é encurtado com afeto: Klaus em alemão, Klaas em neerlandês, Nikos em grego, Kolya em russo. A Europa de Leste remodelou-o em Nikolai, Mykola e Mikuláš, ao passo que a Hungria o tornou Miklós."},"helen":{"pt":"A forma inglesa do grego Helénē, provavelmente de uma palavra que significa «tocha» ou «a brilhante». Foi usada por Helen de Troia, cuja beleza teria «feito zarpar mil navios», e por santa Helena, mãe do imperador Constantine, a quem se atribui o achado da Verdadeira Cruz. Através do latim Helena, tornou-se Elena pelos mundos românico e eslavo meridional e Yelena / Olena no leste, ao passo que o húngaro a remodelou em Ilona."},"catherine":{"pt":"Do grego Aikaterínē, cedo ligado por etimologia popular a katharós, «puro», o que fixou a grafia com -th- no Ocidente. Difundido pelo culto imensamente popular a santa Catherine de Alexandria, tornou-se um dos nomes femininos mais usados da Europa, usado por rainhas e imperatrizes, de Catherine de Medici a Catherine, a Grande. Encurta-se num guarda-roupa inteiro de diminutivos carinhosos — Kate, Katie, Katya, Kasia — um dos quais, o Karin alemão e sueco, é homófono de um nome de menina japonês."},"margaret":{"pt":"Do grego margarítēs (\"pérola\"), palavra que o próprio grego havia tomado emprestada de um Oriente mais distante. O culto a santa Margarida de Antioquia tornou-o predileto por toda a Europa medieval, mais tarde usado por rainhas e por figuras que vão de Margaret Thatcher a Margaret Atwood. Suas formas carinhosas ganharam vida própria — a alemã Greta, a italiana e espanhola Rita, e a inglesa Daisy, visto que o francês marguerite passou a dar nome à flor."},"philip":{"pt":"Do grego Phílippos (\"amigo dos cavalos\"), nome da realeza macedônia usado por Philip II, pai de Alexandre, o Grande. Como nome de um apóstolo, difundiu-se por toda a cristandade e tornou-se predileto dos reis ibéricos — seis Felipe espanhóis e vários Filipe portugueses, de quem as Filipinas recebem o nome. Os britânicos o conhecem sobretudo por Prince Philip, o falecido duque de Edimburgo."},"theodore":{"pt":"Do grego Theódōros (\"dádiva de Deus\"), imagem espelhada de Doroteia. Usado por muitos santos dos primeiros tempos, criou raízes por toda a Europa e além — o russo Fyodor de Dostoiévski e o etíope Tewodros. Em inglês, encanta através dos diminutivos Ted, Teddy e Theo."},"anthony":{"pt":"Do nome de família romano Antōnius, uma antiga gens talvez de origem etrusca cujo membro mais tristemente célebre foi Mark Antony (Marcus Antōnius). Os muitos santos chamados Anthony — sobretudo Antônio, o Grande, e Antônio de Pádua — levaram-no pela cristandade, onde Antonio se tornou um dos nomes mais comuns da Itália e da península ibérica. A grafia com h reflete uma posterior e equivocada ligação ao grego ánthos (\"flor\")."},"julia":{"pt":"O feminino do nome de gens romano Iūlius, a família de Júlio César e do imperador Augusto, o que fez de Iūlia um dos grandes nomes da dinastia júlio-claudiana — tanto a filha de César quanto a filha de Augusto se chamavam Julia. Por muito tempo também nome de uma santa cristã, é hoje um dos nomes de menina mais populares da Europa e das Américas. Seu equivalente masculino perdura como Julius, Julio e Jules."},"lakshmi":{"pt":"Lakshmi é a deusa hindu da riqueza, da fortuna e da beleza, e a consorte de Vishnu, ao lado de cada um de cujos avatares assume uma forma correspondente. O sânscrito lakṣmī deriva de lakṣ “marcar, perceber”, dando o sentido de um sinal auspicioso e, por extensão, de prosperidade. É venerada sobretudo no Diwali, e o seu nome é um dos nomes femininos mais comuns em todo o sul da Índia — embora compostos como Lakshmi Narayan e sobrenomes como Mittal também o usem para homens. Em Bengala, tanto a deusa quanto o nome pronunciam-se Lokkhi."},"arjun":{"pt":"Arjuna é o herói-arqueiro do Mahabharata — o terceiro dos cinco irmãos Pandava, filho do deus Indra e o guerreiro a quem Krishna transmite a Bhagavad Gita no campo de batalha de Kurukshetra. O sânscrito arjuna significa “brilhante, prateado, branco”. Na forma Arjun, é um dos nomes masculinos mais populares da Índia atual, e a epopeia levou a figura por todo o Sudeste Asiático, onde o refinado ksatriya Arjuna (em javanês, Janaka) é um dos favoritos do teatro de sombras wayang."},"sita":{"pt":"Sita é a heroína do Ramayana e a esposa de Rama, um avatar de Lakshmi e o próprio ideal de virtude, devoção e constância. O seu nome sânscrito significa “sulco”: foi encontrada pelo rei Janaka num campo lavrado, filha da deusa da terra Bhumi. A epopeia espalhou-a por todo o Sudeste Asiático — é Nang Sida (นางสีดา) no Ramakien tailandês, Sinta ou Shinta no wayang javanês, e Neang Seda no Reamker cambojano."},"ganesh":{"pt":"Ganesha é o filho de cabeça de elefante de Shiva e Parvati, o amado removedor de obstáculos e patrono dos começos, do saber e das artes, invocado antes de qualquer novo empreendimento. O seu nome sânscrito une gaṇa “hostes, tropas” a īśa “senhor”, e ele é igualmente conhecido como Vinayaka e Ganapati. Na forma Ganesh, é um nome masculino comum na Índia, e a divindade difundiu-se por todo o Sudeste Asiático — venerada na Tailândia como Phra Phikhanet (พระพิฆเนศ), patrono das artes, e na Indonésia como Ganesha, cuja imagem é o emblema do Instituto de Tecnologia de Bandung (ITB)."},"priya":{"pt":"Priya não é um nome de divindade, mas um nome próprio sem mais — o feminino do sânscrito priya “amado, querido”, da raiz prī “agradar”. É um dos nomes femininos mais comuns hoje em toda a Índia, no Nepal, em Bangladesh e no Sri Lanka, e chega com facilidade à diáspora como uma forma simpática e fácil de pronunciar. Em tâmil, o masculino Priyan ou Priya também se usa para homens. A raiz é antiga: é aparentada com o nome da deusa germânica Frigg, ambos do proto-indo-europeu *priH- “amado”."}};
